class PremiumUser {
  calculateCharge(days: number) {
    const base = days * 10;
    return base - this.loyaltyDiscount();
  }
  loyaltyDiscount() { return 5; }
}
class FreeUser {
  calculateCharge(days: number) {
    const base = days * 10;
    return base - this.loyaltyDiscount();
  }
  loyaltyDiscount() { return 0; }
}

abstract class Account {
  // Version A: moved common behavior to superclass
  getFee(days: number) {
    const base = days * 2;
    return base - this.specialDiscount;
  }
}

class GoldAccount extends Account {
  specialDiscount = 5;
}

class SilverAccount extends Account {
  specialDiscount = 2;
}

// Version B: moved common behavior using an abstract helper
abstract class AccountV2 {
  getFee(days: number) {
    const base = days * 2;
    return base - this.getDiscount();
  }
  abstract getDiscount(): number;
}

class GoldAccountV2 extends AccountV2 {
  getDiscount() { return 5; }
}

class SilverAccountV2 extends AccountV2 {
  getDiscount() { return 2; }
}
